Here is the commit message:
ext4: fix bounds check in check_xattrs() to prevent
 out-of-bounds access

The bounds check for the next xattr entry in check_xattrs() uses
(void *)next >= end, which allows next to point within sizeof(u32)
bytes of end. On the next loop iteration, IS_LAST_ENTRY() reads 4
bytes via *(__u32 *)(entry), which can overrun the valid xattr region.

For example, if next lands at end - 1, the check passes since
next < end, but IS_LAST_ENTRY() reads 4 bytes starting at end - 1,
accessing 3 bytes beyond the valid region.

Fix this by changing the check to (void *)next + sizeof(u32) > end,
ensuring there is always enough space for the IS_LAST_ENTRY() read
on the subsequent iteration.

Fixes: 3478c83cf26b ("ext4: improve xattr consistency checking and error reporting")
Cc: stable@vger.kernel.org
Link: https://lore.kernel.org/all/20260224231429.31361-1-kartikey406@gmail.com/T/ [v1]
Signed-off-by: Deepanshu Kartikey <kartikey406@gmail.com>
Link: https://patch.msgid.link/20260328150038.349497-1-kartikey406@gmail.com
Signed-off-by: Theodore Ts'o <tytso@mit.edu>

Here is the root cause:
The bounds check for the next xattr entry in check_xattrs() used `(void *)next >= end`, which allowed `next` to point within `sizeof(u32)` bytes of the buffer's end. On the next loop iteration, `IS_LAST_ENTRY()` reads 4 bytes via `*(__u32 *)(entry)`, and if `next` is at `end - 1`, the check passes but the read accesses 3 bytes beyond the valid region, causing an out-of-bounds access.

Here is the patch:

 static int
 check_xattrs(struct inode *inode, struct buffer_head *bh,
 	     struct ext4_xattr_entry *entry, void *end, void *value_start,
 	     const char *function, unsigned int line)
 {
 	struct ext4_xattr_entry *e = entry;
 	int err = -EFSCORRUPTED;
 	char *err_str;

 	if (bh) {
 		if (BHDR(bh)->h_magic != cpu_to_le32(EXT4_XATTR_MAGIC) ||
 		    BHDR(bh)->h_blocks != cpu_to_le32(1)) {
 			err_str = "invalid header";
 			goto errout;
 		}
 		if (buffer_verified(bh))
 			return 0;
 		if (!ext4_xattr_block_csum_verify(inode, bh)) {
 			err = -EFSBADCRC;
 			err_str = "invalid checksum";
 			goto errout;
 		}
 	} else {
 		struct ext4_xattr_ibody_header *header = value_start;

 		header -= 1;
 		if (end - (void *)header < sizeof(*header) + sizeof(u32)) {
 			err_str = "in-inode xattr block too small";
 			goto errout;
 		}
 		if (header->h_magic != cpu_to_le32(EXT4_XATTR_MAGIC)) {
 			err_str = "bad magic number in in-inode xattr";
 			goto errout;
 		}
 	}

 	/* Find the end of the names list */
 	while (!IS_LAST_ENTRY(e)) {
 		struct ext4_xattr_entry *next = EXT4_XATTR_NEXT(e);
-		if ((void *)next >= end) {
+		if ((void *)next + sizeof(u32) > end) {
 			err_str = "e_name out of bounds";
 			goto errout;
 		}
 		if (strnlen(e->e_name, e->e_name_len) != e->e_name_len) {
 			err_str = "bad e_name length";
 			goto errout;
 		}
 		e = next;
 	}

 	/* Check the values */
 	while (!IS_LAST_ENTRY(entry)) {
 		u32 size = le32_to_cpu(entry->e_value_size);
 		unsigned long ea_ino = le32_to_cpu(entry->e_value_inum);

 		if (!ext4_has_feature_ea_inode(inode->i_sb) && ea_ino) {
 			err_str = "ea_inode specified without ea_inode feature enabled";
 			goto errout;
 		}
 		if (ea_ino && ((ea_ino == EXT4_ROOT_INO) ||
 			       !ext4_valid_inum(inode->i_sb, ea_ino))) {
 			err_str = "invalid ea_ino";
 			goto errout;
 		}
 		if (ea_ino && !size) {
 			err_str = "invalid size in ea xattr";
 			goto errout;
 		}
 		if (size > EXT4_XATTR_SIZE_MAX) {
 			err_str = "e_value size too large";
 			goto errout;
 		}

 		if (size != 0 && entry->e_value_inum == 0) {
 			u16 offs = le16_to_cpu(entry->e_value_offs);
 			void *value;

 			/*
 			 * The value cannot overlap the names, and the value
 			 * with padding cannot extend beyond 'end'.  Check both
 			 * the padded and unpadded sizes, since the size may
 			 * overflow to 0 when adding padding.
 			 */
 			if (offs > end - value_start) {
 				err_str = "e_value out of bounds";
 				goto errout;
 			}
 			value = value_start + offs;
 			if (value < (void *)e + sizeof(u32) ||
 			    size > end - value ||
 			    EXT4_XATTR_SIZE(size) > end - value) {
 				err_str = "overlapping e_value ";
 				goto errout;
 			}
 		}
 		entry = EXT4_XATTR_NEXT(entry);
 	}
 	if (bh)
 		set_buffer_verified(bh);
 	return 0;

 errout:
 	if (bh)
 		__ext4_error_inode(inode, function, line, 0, -err,
 				   "corrupted xattr block %llu: %s",
 				   (unsigned long long) bh->b_blocknr,
 				   err_str);
 	else
 		__ext4_error_inode(inode, function, line, 0, -err,
 				   "corrupted in-inode xattr: %s", err_str);
 	return err;
 }



